{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyNZ33kGpLtkTJnrnkcj2R5s"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"N4uCeyrFNCUd"},"outputs":[],"source":["%%writefile /content/drive/MyDrive/UNet-LIDC-Segmentation/src/model_unet.py\n","import tensorflow as tf\n","from tensorflow.keras import layers, models\n","\n","\n","def conv_block(x, filters):\n","    x = layers.Conv2D(filters, (3, 3), activation=\"relu\", padding=\"same\")(x)\n","    x = layers.Conv2D(filters, (3, 3), activation=\"relu\", padding=\"same\")(x)\n","    return x\n","\n","\n","def build_unet(input_shape=(256, 256, 1)):\n","    \"\"\"\n","    2D U-Net architecture used in the manuscript.\n","    \"\"\"\n","    inputs = layers.Input(input_shape)\n","\n","    # Encoder\n","    c1 = conv_block(inputs, 32)\n","    p1 = layers.MaxPooling2D((2, 2))(c1)\n","\n","    c2 = conv_block(p1, 64)\n","    p2 = layers.MaxPooling2D((2, 2))(c2)\n","\n","    c3 = conv_block(p2, 128)\n","    p3 = layers.MaxPooling2D((2, 2))(c3)\n","\n","    c4 = conv_block(p3, 256)\n","    p4 = layers.MaxPooling2D((2, 2))(c4)\n","\n","    # Bottleneck\n","    bn = conv_block(p4, 512)\n","\n","    # Decoder\n","    u5 = layers.UpSampling2D((2, 2))(bn)\n","    u5 = layers.Concatenate()([u5, c4])\n","    c5 = conv_block(u5, 256)\n","\n","    u6 = layers.UpSampling2D((2, 2))(c5)\n","    u6 = layers.Concatenate()([u6, c3])\n","    c6 = conv_block(u6, 128)\n","\n","    u7 = layers.UpSampling2D((2, 2))(c6)\n","    u7 = layers.Concatenate()([u7, c2])\n","    c7 = conv_block(u7, 64)\n","\n","    u8 = layers.UpSampling2D((2, 2))(c7)\n","    u8 = layers.Concatenate()([u8, c1])\n","    c8 = conv_block(u8, 32)\n","\n","    outputs = layers.Conv2D(1, (1, 1), activation=\"sigmoid\")(c8)\n","\n","    model = models.Model(inputs=[inputs], outputs=[outputs], name=\"unet_lidc_2d\")\n","    return model\n"]}]}